-- Menus
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("syna-launch-walker"), { description = "Launch apps" })
hl.bind("SUPER + CTRL + E", hl.dsp.exec_cmd("syna-launch-walker -m symbols"), { description = "Emoji picker" })
hl.bind("SUPER + ALT + SPACE", hl.dsp.exec_cmd("syna-menu"), { description = "Syna menu" })
hl.bind("SUPER + ESCAPE", hl.dsp.exec_cmd("syna-menu system"), { description = "System menu" })
hl.bind("XF86PowerOff", hl.dsp.exec_cmd("syna-menu system"), { locked = true, description = "Power menu" })
hl.bind("SUPER + K", hl.dsp.exec_cmd("syna-menu-keybindings"), { description = "Show key bindings" })
hl.bind("XF86Calculator", hl.dsp.exec_cmd("gnome-calculator"), { description = "Calculator" })

-- Aesthetics
hl.bind("SUPER + SHIFT + SPACE", hl.dsp.exec_cmd("syna-toggle-waybar"), { description = "Toggle top bar" })
hl.bind("SUPER + CTRL + SPACE", hl.dsp.exec_cmd("~/.local/bin/rice/syna-theme-bg-next"), { description = "Next background in theme" })
hl.bind("SUPER + SHIFT + CTRL + SPACE", hl.dsp.exec_cmd("syna-menu theme"), { description = "Theme menu" })
hl.bind("SUPER + BACKSPACE", hl.dsp.window.set_prop({ prop = "opaque", value = "toggle" }), { description = "Toggle window transparency" })  -- active window; the converter mangled the old shell form
hl.bind("SUPER + SHIFT + BACKSPACE", hl.dsp.exec_cmd("syna-hyprland-workspace-toggle-gaps"), { description = "Toggle workspace gaps" })

-- Notifications
hl.bind("SUPER + COMMA", hl.dsp.exec_cmd("makoctl dismiss"), { description = "Dismiss last notification" })
hl.bind("SUPER + SHIFT + COMMA", hl.dsp.exec_cmd("makoctl dismiss --all"), { description = "Dismiss all notifications" })
hl.bind("SUPER + CTRL + COMMA", hl.dsp.exec_cmd("makoctl mode -t do-not-disturb && makoctl mode | grep -q 'do-not-disturb' && notify-send \"Silenced notifications\" || notify-send \"Enabled notifications\""), { description = "Toggle silencing notifications" })
hl.bind("SUPER + ALT + COMMA", hl.dsp.exec_cmd("makoctl invoke"), { description = "Invoke last notification" })
hl.bind("SUPER + SHIFT + ALT + COMMA", hl.dsp.exec_cmd("makoctl restore"), { description = "Restore last notification" })

-- Toggle idling
hl.bind("SUPER + CTRL + I", hl.dsp.exec_cmd("syna-toggle-idle"), { description = "Toggle locking on idle" })

-- Toggle nightlight
hl.bind("SUPER + CTRL + N", hl.dsp.exec_cmd("syna-toggle-nightlight"), { description = "Toggle nightlight" })

-- File sharing
hl.bind("SUPER + CTRL + S", hl.dsp.exec_cmd("syna-menu share"), { description = "Share" })

-- Waybar-less information
hl.bind("SUPER + CTRL + ALT + T", hl.dsp.exec_cmd("notify-send \"    $(date +\"%A %H:%M  —  %d %B W%V %Y\")\""), { description = "Show time" })
hl.bind("SUPER + CTRL + ALT + B", hl.dsp.exec_cmd("notify-send \"󰁹    Battery is at $(syna-battery-remaining)%\""), { description = "Show battery remaining" })

-- Control panels
hl.bind("SUPER + CTRL + A", hl.dsp.exec_cmd("syna-launch-audio"), { description = "Audio controls" })
hl.bind("SUPER + CTRL + B", hl.dsp.exec_cmd("syna-launch-bluetooth"), { description = "Bluetooth controls" })
hl.bind("SUPER + CTRL + W", hl.dsp.exec_cmd("syna-launch-wifi"), { description = "Wifi controls" })
hl.bind("SUPER + CTRL + T", hl.dsp.exec_cmd("syna-launch-tui btop"), { description = "Activity" })

-- Dictation
hl.bind("SUPER + CTRL + X", hl.dsp.exec_cmd("voxtype record start"), { description = "Start dictation" })
hl.bind("SUPER + CTRL + X", hl.dsp.exec_cmd("voxtype record stop"), { release = true, description = "Stop dictation" })

-- Lock system
hl.bind("SUPER + CTRL + L", hl.dsp.exec_cmd("syna-lock-screen"), { description = "Lock system" })
